// === NUMERI SICURI PER IL FOGLIO ITALIANO (10/08/2026) ===
// Il gestionale è un foglio in italiano: la virgola è il separatore dei decimali.
// Se ci si scrive "322.50" col punto, Google NON legge 322 euro e 50: legge una DURATA
// di 322 ore e 50 minuti, cioè il numero 13,45. È esattamente quello che è successo alle
// righe 663-666 del 09/08 (tariffa 322.50 diventata 13,45 e la cella passata a formato ora,
// che poi si è trascinato anche sulle righe scritte dopo).
// Questa funzione traduce qualunque scrittura di un importo nel formato che il foglio capisce.
function soldiIT(v) {
  let t = String(v === undefined || v === null ? '' : v).trim();
  if (!t) return '';
  if (t[0] === '=') return t;                       // è una formula: non si tocca
  const negativo = /^-/.test(t);
  t = t.replace(/[€$£\s ]/g, '').replace(/^[-+]/, '');
  if (!/[0-9]/.test(t)) return String(v).trim();     // non è un numero: lascia com'è
  if (!/^[0-9.,]+$/.test(t)) return String(v).trim(); // testo misto (es. "da concordare")
  let intero, dec = '';
  const ultimoP = t.lastIndexOf('.');
  const ultimaV = t.lastIndexOf(',');
  if (ultimaV > ultimoP) {                           // 1.250,50 → decimali dopo la virgola
    intero = t.slice(0, ultimaV).replace(/[.,]/g, '');
    dec = t.slice(ultimaV + 1).replace(/[^0-9]/g, '');
  } else if (ultimoP > ultimaV) {
    const coda = t.slice(ultimoP + 1);
    if (/^[0-9]{3}$/.test(coda) && !t.includes(',')) {
      intero = t.replace(/[.,]/g, '');               // 1.250 → 1250 (punto = migliaia)
    } else {
      intero = t.slice(0, ultimoP).replace(/[.,]/g, '');
      dec = coda.replace(/[^0-9]/g, '');             // 322.50 → 322 e 50
    }
  } else {
    intero = t.replace(/[.,]/g, '');
  }
  if (dec.length > 2) dec = dec.slice(0, 2);         // niente centesimi di centesimo
  if (/^0*$/.test(dec)) dec = '';                    // ",00" non aggiunge nulla
  intero = intero.replace(/^0+(?=\d)/, '');
  if (intero === '') intero = '0';
  let fuori = intero + (dec ? ',' + dec : '');
  return (negativo ? '-' : '') + fuori;
}
function s(v){ return (v ?? '').toString().trim(); }
function stripMaps(v){ var x=s(v); x=x.replace(/<a\b[^>]*>[\s\S]*?<\/a>/gi,''); x=x.replace(/\s*\uD83D\uDDFA\uFE0F?\s*Maps\b/gi,''); return x.replace(/\s{2,}/g,' ').trim(); }
function digits(v){ return s(v).replace(/[^\d]/g,''); }
function toNum(v){ return parseFloat(s(v).replace(',','.')); }
function todayIT(){
  const d = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
  const dd = String(d.getDate()).padStart(2,'0');
  const mm = String(d.getMonth()+1).padStart(2,'0');
  const yy = d.getFullYear();
  return `${dd}/${mm}/${yy}`;
}
const src = $input.item.json;
// =====================
// MODALITÀ RECOVERY
// =====================
const modalitaPatterns = [
  'incassare','contanti','carta','fattura','sconto in fattura',
  'dalla struttura','link','omaggio'
];
let modalitaVal = s(src['Modalità'] ?? src.Modalità);
let noteVal = s(src.Note);
if (modalitaVal === '' && noteVal !== '') {
  const noteLower = noteVal.toLowerCase();
  for (const pat of modalitaPatterns) {
    if (noteLower === pat) {
      modalitaVal = noteVal;
      noteVal = '';
      break;
    }
  }
}
// =====================
// HIDE / ALLERT
// =====================
const data = s(src.Data);
// normalizza la data per il confronto "è oggi?" (accetta sia 04/06/2026 sia "gio 4 giugno 2026")
function normDataIT(v){
  v = s(v);
  let m = v.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return m[1].padStart(2,'0')+'/'+m[2].padStart(2,'0')+'/'+m[3];
  const MESI = {gennaio:'01',febbraio:'02',marzo:'03',aprile:'04',maggio:'05',giugno:'06',luglio:'07',agosto:'08',settembre:'09',ottobre:'10',novembre:'11',dicembre:'12'};
  m = v.toLowerCase().match(/(\d{1,2})\s+(gennaio|febbraio|marzo|aprile|maggio|giugno|luglio|agosto|settembre|ottobre|novembre|dicembre)\s+(\d{4})/);
  if (m) return String(m[1]).padStart(2,'0')+'/'+MESI[m[2]]+'/'+m[3];
  return v;
}
const autista = s(src.Autista);
const cell = digits(src.Cell);
const today = todayIT();
const isOggi = (normDataIT(data) === today);
// REGOLA UFFICIALE (Agostino 04/06/2026): autista assegnato -> SEMPRE Invia + visibile;
// senza autista: oggi -> Invia/visibile, giorno diverso -> Non Inviare/nascosto.
const Hide = (autista !== '') ? false : (isOggi ? false : true);
const Allert =
  (autista === '')
    ? (isOggi ? 'Invia' : 'Non Inviare')
    : 'Invia';
// =====================
// WHATSAPP
// =====================
const formulaWA = '=SE(  INDIRETTO("Y"&RIF.RIGA())="";  "";  "https://wa.me/" & INDIRETTO("X"&RIF.RIGA()) &  "?text=" &  ENCODEURL("Dear, this is Transfer Experience! We\'re reaching out about your transfer."))';
let WhatsApp;
if (cell) {
  const isItalian = cell.startsWith('39');
  const text = isItalian
    ? 'Gentile cliente, qui è Transfer Experience! La stiamo contattando in merito al suo transfer.'
    : "Dear, this is Transfer Experience! We're reaching out about your transfer.";
  WhatsApp = `https://wa.me/${cell}?text=${encodeURIComponent(text)}`;
} else {
  WhatsApp = formulaWA;
}
// =====================
// TARIFFA
// =====================
const modalitaLower = modalitaVal.toLowerCase();
const tariffaInput = s(src.Tariffa);
const tariffaNum = toNum(tariffaInput);
const formulaTariffaLET =
'=SE('
+ 'INDIRETTO("J"&RIF.RIGA())="";'
+ '"";'
+ 'LET('
+ 'r;RIF.RIGA();'
+ 'mezzo;INDIRETTO("M"&r);'
+ 'is_special;O(mezzo="Tuk-tuk FT61049";mezzo="Ape Calessino DD63585");'
+ 'alias;CERCA.X(INDIRETTO("J"&r);\'Fornitori e strutture\'!A:A;SE(is_special;\'Fornitori e strutture\'!C:C;\'Fornitori e strutture\'!B:B));'
+ 'pax;VALORE(INDIRETTO("H"&r));'
+ 'range_B;VALORE(INDIRETTO("\'\"&alias&\"\'!B1"));'
+ 'range_C;VALORE(INDIRETTO("\'\"&alias&\"\'!C1"));'
+ 'col;SE(pax<=range_B;2;SE(pax<=range_C;3;4));'
+ 'prezzoF;SE.ERRORE(CERCA.VERT(INDIRETTO("F"&r);INDIRETTO(alias&"!A:D");col;FALSO);0);'
+ 'prezzoG;SE.ERRORE(CERCA.VERT(INDIRETTO("G"&r);INDIRETTO(alias&"!A:D");col;FALSO);0);'
+ 'prezzoBase;MAX(prezzoF;prezzoG);'
+ 'extra;SE.ERRORE('
+ 'CERCA.X(INDIRETTO("J"&r);\'Fornitori e strutture\'!A:A;\'Fornitori e strutture\'!D:D)'
+ '*'
+ 'CERCA.X(INDIRETTO("N"&r);\'Fornitori e strutture\'!Q:Q;\'Fornitori e strutture\'!R:R)'
+ ';0);'
+ 'moltip;SE(INDIRETTO("E"&r)="";1;SE(VALORE(STRINGA.ESTRAI(INDIRETTO("E"&r);1;2))<7;1,2;1));'
+ '(prezzoBase*moltip)+extra'
+ ')'
+ ')';
let Tariffa;
if (modalitaLower === 'omaggio') Tariffa = '0';
else if (tariffaInput !== '') Tariffa = soldiIT(tariffaInput);
else Tariffa = formulaTariffaLET;
// =====================
// ACCONTO
// =====================
const accontoInput = s(src.Acconto);
const accontoNum = toNum(accontoInput);
const Acconto = (!isNaN(accontoNum) && accontoNum > 0)
  ? '-' + soldiIT(accontoInput)
  : accontoInput;
// =====================
// PERCENTUALE + FEE (logica incrociata)
// =====================
const percentualeInput = s(src['%']);
const feeRaw = s(src.Fee).replace(/[^\d,.]/g, '');
const feeNum = toNum(feeRaw);
const feeIsPercentageBug = (!isNaN(feeNum) && feeNum > 0 && feeNum <= 1);
const feeValorizzata = (feeRaw !== '' && !feeIsPercentageBug);
const percentualeZero = (percentualeInput === '0');
let percentualeDecimale = '';
if (percentualeInput !== '') {
  const pNum = toNum(percentualeInput);
  percentualeDecimale = (!isNaN(pNum) && pNum > 1)
    ? String(pNum / 100).replace('.', ',')
    : String(pNum).replace('.', ',');
}
const formulaPercentuale =
'=SE(\n'
+ '  INDIRETTO("J"&RIF.RIGA())="";\n'
+ '  0;\n'
+ '  CERCA.X(\n'
+ '    INDIRETTO("J"&RIF.RIGA());\n'
+ '    \'Fornitori e strutture\'!A:A;\n'
+ '    \'Fornitori e strutture\'!E:E;\n'
+ '    0\n'
+ '  )\n'
+ ')';
const formulaFee =
'=SE('
+ 'INDIRETTO("V"&RIF.RIGA())="Sconto in fattura";'
+ '0;'
+ 'SE('
+ 'O('
+ 'INDIRETTO("S"&RIF.RIGA())="pagata";'
+ 'INDIRETTO("S"&RIF.RIGA())=""'
+ ');'
+ '-INDIRETTO("Q"&RIF.RIGA())*INDIRETTO("O"&RIF.RIGA());'
+ '""'
+ ')'
+ ')';
let Percentuale;
let Fee;
if (percentualeZero) {
  Percentuale = '0';
  Fee = '0';
} else if (feeValorizzata && percentualeInput === '') {
  const feeNumPos = toNum(feeRaw);
  if (!isNaN(feeNumPos) && !isNaN(tariffaNum) && tariffaNum > 0) {
    const calcolata = feeNumPos / tariffaNum;
    Percentuale = String(Math.round(calcolata * 10000) / 10000).replace('.', ',');
  } else {
    Percentuale = formulaPercentuale;
  }
  Fee = '-' + soldiIT(feeRaw);
} else if (!feeValorizzata && percentualeInput !== '') {
  Percentuale = percentualeDecimale;
  Fee = formulaFee;
} else if (feeValorizzata && percentualeInput !== '') {
  Percentuale = percentualeDecimale;
  Fee = '-' + soldiIT(feeRaw);
} else {
  Percentuale = formulaPercentuale;
  Fee = formulaFee;
}
// =====================
// PULIZIA NOTE: link su riga separata e senza virgolette
// =====================
const noteClean = noteVal
  .replace(/"(https?:\/\/[^\s"<>]+)"/g, '$1')          // rimuovi virgolette attorno agli URL
  .replace(/([^\n])(https?:\/\/[^\s<>]+)/g, '$1\n$2')  // newline PRIMA del link
  .replace(/(https?:\/\/[^\s<>]+)(\s|$)/g, '$1\n$2')   // newline DOPO il link (fix bug 2026-05-14: lookahead spezzava URL a fine testo)
  .replace(/\n{2,}/g, '\n')                              // elimina doppie righe vuote
  .trim();
// =====================
// HYPERLINK: se la nota contiene un URL, la cella diventa una formula
// HYPERLINK che mostra la nota intera ma è cliccabile (apre il primo URL).
// I workflow a valle leggono FORMATTED_VALUE → vedono il testo come prima.
// =====================
const _urlMatch = noteClean.match(/https?:\/\/[^\s<>]+/);
const noteOut = _urlMatch
  ? '=HYPERLINK("' + _urlMatch[0] + '";' + noteClean.split('\n').map(_s => '"' + _s.replace(/"/g, '""') + '"').join('&CHAR(10)&') + ')'
  : noteClean;
// ======================
// OUTPUT (merge-safe)
// ======================
// Netto formula (dinamica)
const formulaNetto = '=SE(INDIRETTO("V"&RIF.RIGA())="sconto in fattura"; INDIRETTO("O"&RIF.RIGA()) * (1 - INDIRETTO("Q"&RIF.RIGA())); INDIRETTO("O"&RIF.RIGA()) + INDIRETTO("R"&RIF.RIGA()))';
// Merge safety: per update, escludi campi AI vuoti
const isUpdate = !!s(src.Id);
const out = {};
// Id per matching
if (s(src.Id)) out['Id'] = s(src.Id);
// Campi sistema/calcolati - sempre inclusi
out['Allert'] = Allert;
out['Hide'] = Hide;
out['Note'] = noteOut;
out['WhatsApp'] = WhatsApp;
out['Tariffa'] = Tariffa;
out['Acconto'] = Acconto;
out['%'] = Percentuale;
out['Fee'] = Fee;
out['Netto'] = formulaNetto;
out['Modalit\u00e0'] = modalitaVal;
out['Stato %'] = s(src['Stato_Percentuale'] || src['Stato %'] || '');
// Campi AI - includi solo se non vuoti durante update
const aiMap = {
  'Data': data,
  'Time': s(src.Time),
  'Transfer > Da': s(src.Transfer_Da),
  'Transfer < Per': s(src.Transfer_Per),
  'Pax': s(src.Pax),
  'Nome': s(src.Nome),
  'Fornitori': s(src.Fornitori),
  'Volo': s(src.Volo),
  'Autista': autista,
  'Veicolo': s(src.Veicolo),
  'h extra': s(src.H_extra),
  'Cell.': s(src.Cell)
};
for (const [key, val] of Object.entries(aiMap)) {
  const cv = stripMaps(val);
  if (!isUpdate || cv !== '') {
    out[key] = cv;
  }
}
return { json: out };

// ===== MAPPATURA FORNITORI → EMAIL =====
const FORNITORI_EMAIL = {
  "talea group la peschiera": {
    to: "info@peschierahotel.com",
    cc: ["frontoffice@peschierahotel.com", "francesca.desario@taleacollection.com"]
  }
  // Aggiungi altri fornitori qui:
  // "nome fornitore": { to: "email@esempio.com", cc: ["cc1@esempio.com"] }
};

// ===== HELPERS =====
function s(v) { return (v ?? '').toString().trim(); }

function formatIT(n) {
  if (n === null || n === undefined || !Number.isFinite(n)) return '';
  return n.toFixed(2).replace('.', ',');
}

function toNum(v) {
  const s0 = s(v);
  if (!s0) return null;
  let str = s0.replace(/\s+/g, '').replace(/[€$£]/g, '');
  if (str.includes(',')) {
    str = str.replace(/\./g, '').replace(/,/g, '.');
  }
  str = str.replace(/[^0-9.+-]/g, '');
  const n = Number(str);
  return Number.isFinite(n) ? n : null;
}

function parseCalendarDate(dataServizio) {
  let giorno, mese, anno;

  const slashMatch = dataServizio.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (slashMatch) {
    giorno = slashMatch[1].padStart(2, '0');
    mese = slashMatch[2].padStart(2, '0');
    anno = slashMatch[3];
  }

  if (!anno) {
    const mesiIT = { gennaio:'01', febbraio:'02', marzo:'03', aprile:'04', maggio:'05', giugno:'06', luglio:'07', agosto:'08', settembre:'09', ottobre:'10', novembre:'11', dicembre:'12' };
    const textMatch = dataServizio.match(/(\d{1,2})\s+(\w+)\s+(\d{4})/);
    if (textMatch) {
      giorno = textMatch[1].padStart(2, '0');
      mese = mesiIT[textMatch[2].toLowerCase()] || '01';
      anno = textMatch[3];
    }
  }

  return { giorno, mese, anno };
}

// ===== PARSA TUTTI I TRANSFER DALL'OUTPUT DEL MODELLO =====
const raw = $json?.output?.[0]?.content?.[0]?.text ?? $json?.content?.[0]?.text ?? $json?.text ?? '{}';
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [{ json: { email: '', emailCC: '', emailSubject: '', emailBody: '', skipped: true, error: 'JSON parse error' } }];
}

const transfers = parsed?.transfers || [];
if (transfers.length === 0) {
  return [{ json: { email: '', emailCC: '', emailSubject: '', emailBody: '', skipped: true, error: 'No transfers' } }];
}

// ===== RAGGRUPPA PER FORNITORE =====
const grouped = {};

for (const tr of transfers) {
  const fornitore = s(tr.Fornitori || tr.Fornitore || '').toLowerCase();
  const match = FORNITORI_EMAIL[fornitore];
  if (!match) continue;

  if (!grouped[fornitore]) {
    grouped[fornitore] = {
      match: match,
      nomeStruttura: s(tr.Fornitori || tr.Fornitore || ''),
      transfers: []
    };
  }
  grouped[fornitore].transfers.push(tr);
}

// Se nessun fornitore nella mappatura → skip
const fornitori = Object.keys(grouped);
if (fornitori.length === 0) {
  return [{ json: { email: '', emailCC: '', emailSubject: '', emailBody: '', skipped: true } }];
}

// ===== GENERA UN OUTPUT PER OGNI FORNITORE =====
const outputs = [];

for (const fornitoreKey of fornitori) {
  const group = grouped[fornitoreKey];
  const nomeStruttura = group.nomeStruttura || 'Transfer Experience';
  const trs = group.transfers;

  // ===== TESTI (EN) =====
  const t = {
    title: 'Transfer Booking Confirmation',
    subtitle: nomeStruttura,
    intro: `Thank you for booking your transfer service with ${nomeStruttura}. Please find below your booking details:`,
    detailsTitle: 'Transfer Details',
    date: 'Date', time: 'Time', from: 'Pick-up', to: 'Drop-off',
    pax: 'Passengers', flight: 'Flight', vehicle: 'Vehicle', phone: 'Phone',
    notes: 'Notes', price: 'Fare',
    policyTitle: '⚠️ Cancellation Policy',
    policyFree: '✅ FREE cancellation up to 24 hours before the service',
    policyPaid: '❌ Cancellation within 24 hours: 100% of the fare will be charged',
    policyNote: 'For changes or cancellations, please contact us promptly.',
    calendarBtn: '📅 Add to Google Calendar',
    footer: `Transfer Experience for ${nomeStruttura}`,
    questions: 'If you have any questions, please don\'t hesitate to contact us.',
    nd: 'N/A'
  };

  // ===== SUBJECT =====
  let emailSubject;
  if (trs.length === 1) {
    const tr0 = trs[0];
    emailSubject = `🚗 Transfer Confirmation - ${s(tr0.Nome) || 'Guest'} - ${s(tr0.Data)} at ${s(tr0.Time)}`;
  } else {
    emailSubject = `🚗 ${trs.length} Transfer Confirmations - ${nomeStruttura}`;
  }

  // ===== GENERA TABELLA PER OGNI TRANSFER =====
  let transferBlocks = '';

  for (let idx = 0; idx < trs.length; idx++) {
    const tr = trs[idx];
    const dataServizio = s(tr.Data);
    const ora = s(tr.Time);
    const trs_da = s(tr.Transfer_Da || tr['Transfer > Da'] || '');
    const trs_per = s(tr.Transfer_Per || tr['Transfer < Per'] || '');
    const nome = s(tr.Nome);
    const paxVal = s(tr.Pax);
    const volo = s(tr.Volo);
    let veicolo = s(tr.Veicolo);
    const note = s(tr.Note);
    const cellulare = s(tr.Cell || tr['Cell.'] || '');
    const tariffa = toNum(tr.Tariffa);

    // Se veicolo vuoto → assegna in base ai pax
    if (!veicolo) {
      const paxNum = parseInt(paxVal);
      if (!isNaN(paxNum) && paxNum > 0) {
        if (paxNum <= 2) veicolo = 'Car';
        else if (paxNum <= 7) veicolo = 'Minivan';
        else veicolo = 'Minibus';
      }
    }

    // Calendar link
    let calendarLink = '';
    if (dataServizio && ora && ora.includes(':')) {
      const { giorno, mese, anno } = parseCalendarDate(dataServizio);
      if (anno) {
        const timeParts = ora.split(':');
        const oreStr = timeParts[0].padStart(2, '0');
        const minutiStr = timeParts[1].padStart(2, '0');
        const startDT = `${anno}${mese}${giorno}T${oreStr}${minutiStr}00`;
        const oreFine = String(parseInt(oreStr) + 2).padStart(2, '0');
        const endDT = `${anno}${mese}${giorno}T${oreFine}${minutiStr}00`;
        const calTitle = encodeURIComponent(`Transfer: ${nome || 'Ospite'} - ${nomeStruttura}`);
        const calLocation = encodeURIComponent(`${trs_da} → ${trs_per}`);
        const calDetails = encodeURIComponent([
          `Cliente: ${nome || 'N/D'}`,
          `Pax: ${paxVal || t.nd}`,
          volo ? `Volo: ${volo}` : '',
          veicolo ? `Veicolo: ${veicolo}` : '',
          cellulare ? `Cellulare: ${cellulare}` : '',
          note ? `Note: ${note}` : ''
        ].filter(Boolean).join('\n'));
        calendarLink = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${calTitle}&dates=${startDT}/${endDT}&details=${calDetails}&location=${calLocation}`;
      }
    }

    const tariffaRow = tariffa !== null
      ? `<tr style="background-color:#f8f9fa;"><td style="padding:12px;border:1px solid #dee2e6;font-weight:bold;">💰 ${t.price}</td><td style="padding:12px;border:1px solid #dee2e6;">€ ${formatIT(tariffa)}</td></tr>`
      : '';

    const noteRow = note
      ? `<tr style="background-color:#fff3cd;"><td style="padding:12px;border:1px solid #dee2e6;font-weight:bold;">📝 ${t.notes}</td><td style="padding:12px;border:1px solid #dee2e6;">${note}</td></tr>`
      : '';

    // Header per transfer multipli
    const blockHeader = trs.length > 1
      ? `<h3 style="color:#2c3e50;border-bottom:2px solid #3498db;padding-bottom:10px;margin-top:30px;">🚗 Transfer ${idx + 1} di ${trs.length}</h3>`
      : `<h3 style="color:#2c3e50;border-bottom:2px solid #3498db;padding-bottom:10px;margin-top:30px;">🚗 ${t.detailsTitle}</h3>`;

    transferBlocks += `
${blockHeader}
<table style="width:100%;border-collapse:collapse;margin:20px 0;">
<tr style="background-color:#f8f9fa;"><td style="padding:12px;border:1px solid #dee2e6;font-weight:bold;width:140px;">📅 ${t.date}</td><td style="padding:12px;border:1px solid #dee2e6;">${dataServizio}</td></tr>
<tr><td style="padding:12px;border:1px solid #dee2e6;font-weight:bold;">🕐 ${t.time}</td><td style="padding:12px;border:1px solid #dee2e6;">${ora}</td></tr>
<tr style="background-color:#f8f9fa;"><td style="padding:12px;border:1px solid #dee2e6;font-weight:bold;">📍 ${t.from}</td><td style="padding:12px;border:1px solid #dee2e6;">${trs_da || t.nd}</td></tr>
