const items = $input.all();

return items.map(it => {
  const j = it.json || {};
  // Sanitize Id: rimuove tag HTML (es. <code>TR/..</code> arrivati dal recap Telegram)
  if (j.Id) { j.Id = j.Id.toString().replace(/<[^>]+>/g, '').trim(); }
  // === GUARDIA NOTE (11/07/2026) — la Note è per l'autista/il cliente, NON per l'AI ===
  // Scarta le frasi in cui il modello racconta il proprio ragionamento
  // (Id provvisori, fuzzy match, turni precedenti, "lo salvo così"...).
  const META_RX = /(fuzzy|match|id provvision|id provvisor|turno precedente|messaggio precedente|recap ufficiale|recap precedente|l'utente ha detto|lo salvo|salvo come scritto|ambigu|callback|\[?intent\b|prompt|tool_|il sistema|come da mia (?:nota|analisi))/i;
  const noteKey = ['Note','note','NOTE'].find(k => j[k] !== undefined && j[k] !== null);
  if (noteKey) {
    const rawNote = String(j[noteKey] || '');
    if (rawNote.trim()) {
      const kept = rawNote
        .split(/(?<=[.!?])\s+|\n+/)
        .filter(s => s.trim() && !META_RX.test(s))
        .join(' ')
        .replace(/^\s*Nota(?:\s+su[^:]*)?:\s*/i, '')
        .replace(/\s{2,}/g, ' ')
        .trim();
      if (kept !== rawNote.trim()) {
        j._noteOriginal = rawNote;
        j._noteCleaned = true;
      }
      j[noteKey] = kept;
    }
  }

  const missing = [];

  if (!j.Data && !j.data) missing.push('Data');
  if (!j.Time && !j.time && !j.Ora && !j.ora) missing.push('Ora');
  if (!j['Transfer_Da'] && !j['Transfer > Da'] && !j.da) missing.push('Da');
  if (!j['Transfer_Per'] && !j['Transfer < Per'] && !j.per) missing.push('Per');

  return {
    json: Object.assign({}, j, {
      _missingFields: missing.length > 0 ? missing : undefined
    })
  };
});

